/* global cvAdd */
function p14Fixture() {
  const fx = homeFixture();
  fx.dirs.push('/home/user/sec');
  fx.files.push(
    ['/home/user/sec/audit.rules', { content: '-D\n-b 8192\n-w /etc/passwd -p wa -k identity\n-w /etc/shadow -p wa -k identity\n-w /etc/sudoers -p wa -k sudo_changes\n-w /var/log/lastlog -p wa -k logins\n-e 2\n' }],
    ['/home/user/sec/jail.local', { content: '[DEFAULT]\nbantime = 1h\nfindtime = 10m\nmaxretry = 5\n\n[sshd]\nenabled = true\nmaxretry = 3\n' }],
    ['/home/user/sec/sudoers-ops', { content: '%ops ALL=(root) /usr/bin/systemctl restart nginx\ndana ALL=(root) NOPASSWD: ALL\nomer ALL=(root) NOEXEC: /usr/bin/less\n' }],
  );
  return fx;
}
const p14Out = cmd => { const sh = new Shell(p14Fixture()); const r = sh.run(cmd); return r.out + r.err; };
const p14Shown = (log, cmd) => { const want = p14Out(cmd).trim(); return !!want && log.some(l => l.out.trim() === want); };
const p14Sudo = (...cmds) => cmds.flatMap(c => [c, `sudo ${c}`]);

const UNIT_92 = {
  section: 10, unit: 92, exams: ['C3.1', 'C3.3', 'C3.4', 'C3.6', 'C5.4'], title: T('כלי אבטחה', 'Security tools'), subtitle: T('PAM, ‏auditd, ‏fail2ban, ‏chattr ו־sudo מוקשח', 'PAM, auditd, fail2ban, chattr and a hardened sudo'), color: 'purple', fixture: p14Fixture,
  lessons: [
    { title: T('PAM וכניסה מספרייה', 'PAM and directory logins'), exercises: [
      { type: 'teach', cmd: '/etc/pam.d', name: 'pluggable authentication', text: T('PAM היא השכבה שכל תוכנה עם כניסה (login, ‏sshd, ‏sudo, ‏su) שואלת: "האם המשתמש הזה בסדר?". לכל תוכנה יש קובץ ב־‎/etc/pam.d/‎, ובו שורות של מודולים, למשל pam_unix.so שבודק סיסמה מול ‎/etc/shadow‎. ההגדרות של המודולים עצמם יושבות ב־‎/etc/security/‎. כך משנים את שיטת הכניסה בלי לגעת בתוכנה עצמה.', 'PAM is the layer every program with a login (login, sshd, sudo, su) asks: "is this user OK?". Each program has a file in /etc/pam.d/, holding lines of modules, for example pam_unix.so, which checks a password against /etc/shadow. Settings for the modules themselves live in /etc/security/. That way you change how logins work without touching the program.') },
      { type: 'output', prompt: T('על שרת Ubuntu אמיתי הריצו ‎ls /etc/pam.d‎ (שמונה השמות הראשונים בשורה אחת). מה הודפס?', 'On a real Ubuntu server ls /etc/pam.d ran (the first eight names on one line). What was printed?'), rec: 'p14-pam-ls', wrongText: ['faillock.conf limits.conf pwquality.conf access.conf', 'passwd shadow group gshadow sudoers'] },
      { type: 'teach', cmd: 'auth required', name: 'four types, four flags', text: T('כל שורה ב־PAM בנויה מסוג, דגל ומודול. הסוגים: auth (מי אתה, למשל סיסמה), ‏account (האם מותר לך עכשיו, למשל חשבון שפג תוקפו), ‏password (החלפת סיסמה) ו־session (מה קורה בכניסה וביציאה). הדגלים: required חייב להצליח אבל ממשיך לבדוק, requisite נכשל מיד, sufficient מספיק לבד אם אין כישלון קודם, ו־optional לא משנה את התוצאה.', 'Each PAM line is built from a type, a flag and a module. The types: auth (who you are, for example a password), account (whether you may log in now, for example an expired account), password (changing a password) and session (what happens at login and logout). The flags: required must succeed but keeps checking, requisite fails at once, sufficient is enough alone if nothing failed before it, and optional does not change the result.') },
      { type: 'output', prompt: T('על אותו שרת הריצו grep על ‎/etc/pam.d/common-auth‎ בלי הערות ושורות ריקות. מה הודפס?', 'On the same server grep ran on /etc/pam.d/common-auth without comments and empty lines. What was printed?'), rec: 'p14-pam-auth', wrongText: ['account required pam_unix.so\nsession optional pam_systemd.so', 'auth sufficient pam_permit.so'] },
      { type: 'match', prompt: T('התאימו כל סוג שורה ב־PAM לתפקיד שלו', 'Match each PAM line type to its job'), pairs: [['auth', T('מי אתה', 'who you are')], ['account', T('האם מותר לך עכשיו', 'whether you may log in now')], ['password', T('החלפת סיסמה', 'changing a password')], ['session', T('מה קורה בכניסה וביציאה', 'what happens at login and logout')]] },
      { type: 'sentence', prompt: READ, text: T('הדגל ___ נכשל מיד ולא ממשיך לבדוק את השורות הבאות.', 'The ___ flag fails at once and does not go on to the next lines.'), options: ['requisite', 'required', 'optional'], answer: 'requisite' },
      { type: 'teach', cmd: 'sssd, realm', name: 'users from a directory', text: T('בארגון גדול המשתמשים לא נשמרים בכל שרת, אלא בספרייה מרכזית. LDAP היא הספרייה (פורט 389, או LDAPS ב־636). ‏Kerberos נותנת "כרטיס" אחרי כניסה אחת, כך שלא מקלידים סיסמה בכל שרת (kinit מבקשת כרטיס, klist מציגה אותו). ‏SSSD הוא השירות שמחבר את לינוקס ל־LDAP, ל־Kerberos או ל־Active Directory, ושומר עותק כדי שאפשר יהיה להיכנס גם כשהשרת המרכזי לא זמין. Winbind הוא הרכיב של Samba שעושה את זה מול AD. ‏‎realm join‎ מצטרפת לדומיין ומגדירה את SSSD בשבילכם.', 'In a large organisation users are not stored on every server, but in a central directory. LDAP is the directory (port 389, or LDAPS on 636). Kerberos gives you a "ticket" after one login, so you do not type a password on every server (kinit asks for a ticket, klist shows it). SSSD is the service that connects Linux to LDAP, Kerberos or Active Directory, and keeps a copy so you can log in even when the central server is down. Winbind is Samba\'s part that does this against AD. realm join joins a domain and sets up SSSD for you.') },
      { type: 'match', prompt: T('התאימו כל שם לתפקיד שלו', 'Match each name to its job'), pairs: [['LDAP', T('ספריית המשתמשים המרכזית', 'the central user directory')], ['Kerberos', T('כרטיס אחרי כניסה אחת', 'a ticket after one login')], ['SSSD', T('מחבר את לינוקס לספרייה, עם עותק שמור', 'connects Linux to the directory, with a saved copy')], ['Winbind', T('הרכיב של Samba מול Active Directory', 'Samba\'s part for Active Directory')]] },
      { type: 'choice', prompt: T('משתמשי AD לא מצליחים להיכנס לשרת כשהחיבור לדומיין נופל, אבל משתמשים מקומיים כן. איזה שירות כדאי לבדוק קודם?', 'AD users cannot log in to a server when the link to the domain drops, but local users can. Which service should you check first?'), options: ['sssd', 'sshd', 'auditd', 'polkit'], answer: 'sssd',
        why: { sshd: T('משתמשים מקומיים נכנסים דרך אותו sshd, אז הוא עובד.', 'Local users log in through the same sshd, so it works.'), auditd: T('auditd רק רושם אירועים.', 'auditd only records events.'), polkit: T('polkit מחליטה על פעולות אחרי הכניסה, לא על הכניסה עצמה.', 'polkit decides on actions after login, not on the login itself.') } },
    ] },
    { title: T('נעילה, ‏sudo, ‏rbash ו־polkit', 'Lockout, sudo, rbash and polkit'), exercises: [
      { type: 'teach', cmd: 'pam_faillock', name: 'lock after failed logins', text: T('נעילת חשבון אחרי כמה ניסיונות כושלים עוצרת ניחוש סיסמאות. פעם עשו את זה עם pam_tally2, אבל הוא הוסר מ־Linux-PAM בגרסה 1.5. היום משתמשים ב־pam_faillock: ההגדרות ב־‎/etc/security/faillock.conf‎ ‏(deny=3 נועל אחרי שלושה כישלונות, ‏unlock_time=600 משחרר אחרי 10 דקות). ‎faillock --user dana‎ מציגה את הכישלונות, ו־‎--reset‎ משחררת.', 'Locking an account after a few failed attempts stops password guessing. This used to be done with pam_tally2, but it was removed from Linux-PAM in version 1.5. Today you use pam_faillock: its settings are in /etc/security/faillock.conf (deny=3 locks after three failures, unlock_time=600 unlocks after 10 minutes). faillock --user dana shows the failures, and --reset unlocks.') },
      { type: 'output', prompt: T('המשתמש dana עוד לא נכשל בכניסה. על שרת Ubuntu אמיתי הריצו ‎faillock --user dana‎ ואז את קוד היציאה. מה הודפס?', 'The user dana has not failed a login yet. On a real Ubuntu server faillock --user dana ran, then the exit code. What was printed?'), rec: 'p14-faillock', wrongText: ['dana:\nWhen Type Source Valid\n2026-11-08 10:00:00 RHOST 203.0.113.7 V\nexit: 0', 'faillock: user dana is locked\nexit: 1'] },
      { type: 'teach', cmd: 'visudo -c', name: 'a safer sudo', text: T('sudo נלמד כבר. להקשחה: עורכים רק עם visudo, שבודקת תחביר לפני שמירה, כי שגיאה ב־sudoers יכולה לנעול את כולם בחוץ. קובץ לכל צוות ב־‎/etc/sudoers.d/‎, ובדיקה עם ‎visudo -cf FILE‎. ‏NOPASSWD מדלג על הסיסמה, אז נותנים אותו רק לפקודה אחת ולא ל־ALL. ‏NOEXEC מונע מהתוכנה להריץ תוכנות אחרות, למשל ‎!sh‎ מתוך less, שהיה פותח shell של root.', 'You already know sudo. To harden it: edit only with visudo, which checks the syntax before saving, because a mistake in sudoers can lock everyone out. One file per team in /etc/sudoers.d/, checked with visudo -cf FILE. NOPASSWD skips the password, so give it for one command only, never for ALL. NOEXEC stops the program from running other programs, for example !sh inside less, which would open a root shell.'), known: true },
      { type: 'output', prompt: T('הקובץ bad מכיל את השורה ‎dana ALL=(root) NOPASSWD /usr/bin/ls‎ (חסרות נקודתיים אחרי NOPASSWD). על שרת Ubuntu אמיתי הריצו ‎visudo -cf bad‎. מה הודפס?', 'The file bad holds the line dana ALL=(root) NOPASSWD /usr/bin/ls (no colon after NOPASSWD). On a real Ubuntu server visudo -cf bad ran. What was printed?'), rec: 'p14-visudo-bad', wrongRec: ['p14-visudo-ok'], wrongText: ['bad: parsed OK'] },
      { type: 'choice', prompt: T('הקובץ sec/sudoers-ops מכיל שלוש שורות: ‏%ops מקבלים systemctl restart nginx, ‏dana מקבלת ‎NOPASSWD: ALL‎, ו־omer מקבל ‎NOEXEC: /usr/bin/less‎. איזו שורה הכי מסוכנת?', 'The file sec/sudoers-ops holds three lines: %ops get systemctl restart nginx, dana gets NOPASSWD: ALL, and omer gets NOEXEC: /usr/bin/less. Which line is the most dangerous?'), plain: true,
        options: [T('dana: כל פקודה כ־root, בלי סיסמה', 'dana: any command as root, with no password'), T('%ops: פקודה אחת בלבד', '%ops: one command only'), T('omer: less עם NOEXEC', 'omer: less with NOEXEC'), T('אף אחת, כולן בטוחות', 'None, they are all safe')],
        why: [null, T('פקודה אחת עם סיסמה היא בדיוק הדרך הנכונה.', 'One command with a password is exactly the right way.'), T('NOEXEC סוגרת את הבריחה ל־shell מתוך less.', 'NOEXEC closes the escape to a shell from less.'), T('מי שגונב את החשבון של dana מקבל root מיד.', 'Whoever steals dana\'s account gets root at once.')] },
      { type: 'teach', cmd: '/bin/rbash', name: 'a restricted shell', text: T('‏‎/bin/rbash‎ היא bash במצב מוגבל: אסור cd, אסור לשנות PATH, אסור להריץ פקודה עם / בשם ואסור להפנות פלט לקובץ. נותנים אותה למשתמש שצריך רק כמה פקודות, ושמים ב־PATH שלו רק אותן. היא לא חומה אמיתית: אם יש לו תוכנה שפותחת shell, הוא בורח. למשתמש שלא אמור להיכנס בכלל נותנים ‎/sbin/nologin‎, שמסרבת בנימוס.', '/bin/rbash is bash in restricted mode: no cd, no changing PATH, no command with / in its name and no redirecting output to a file. You give it to a user who needs only a few commands, and put only those in his PATH. It is not a real wall: if he has a program that opens a shell, he escapes. A user who should not log in at all gets /sbin/nologin, which refuses politely.') },
      { type: 'output', prompt: T('על שרת Ubuntu אמיתי הריצו ‎ls -l /bin/rbash‎ (השם, החץ והיעד), ואז ברבש ‎cd /tmp‎, ‏‎/usr/bin/ls‎ ו־‎echo hi > x.txt‎. מה הודפס?', 'On a real Ubuntu server ls -l /bin/rbash ran (name, arrow and target), then in rbash cd /tmp, /usr/bin/ls and echo hi > x.txt. What was printed?'), rec: 'p14-rbash', wrongText: ['/bin/rbash -> bash\nx.txt', '/bin/rbash -> dash\nrbash: line 1: cd: restricted'] },
      { type: 'teach', cmd: 'polkit', name: 'permission for one action', text: T('polkit מחליטה אם משתמש רגיל יכול לבקש פעולה של מנהל דרך שירות, למשל להפעיל מחדש שירות או לכבות את המחשב, בלי sudo מלא. כל פעולה מקבלת שם, והתשובה יכולה להיות yes, ‏no, ‏auth_admin (צריך סיסמה של מנהל) או auth_admin_keep (וזוכרים אותה לכמה דקות). כללים משלכם כותבים ב־‎/etc/polkit-1/rules.d/‎. ‏pkaction מציגה פעולות, ו־pkexec מריצה פקודה כמשתמש אחר.', 'polkit decides whether a regular user may ask a service for an admin action, for example restarting a service or shutting down, without full sudo. Each action has a name, and the answer can be yes, no, auth_admin (an admin password is needed) or auth_admin_keep (and it is remembered for a few minutes). Your own rules go in /etc/polkit-1/rules.d/. pkaction lists actions, and pkexec runs a command as another user.') },
      { type: 'output', prompt: T('על שרת Ubuntu אמיתי הריצו pkaction על הפעולה org.freedesktop.systemd1.manage-units וסיננו את התיאור ואת התשובות. מה הודפס?', 'On a real Ubuntu server pkaction ran on the action org.freedesktop.systemd1.manage-units, keeping the description and the answers. What was printed?'), rec: 'p14-pkaction', wrongText: [' description: Manage system services or other units\n implicit any: yes\n implicit inactive: yes\n implicit active: yes', ' description: Reboot the system\n implicit any: no\n implicit inactive: no\n implicit active: no'] },
    ] },
    { title: T('auditd ו־SELinux', 'auditd and SELinux'), exercises: [
      { type: 'teach', cmd: 'auditctl', name: 'record who did what', text: T('auditd רושם אירועים של הליבה ל־‎/var/log/audit/audit.log‎: מי פתח, שינה או הריץ קובץ. זה החלק של accounting: לדעת אחר כך מה קרה. ‎auditctl -w /etc/passwd -p wa -k passwd_watch‎ שומרת על הקובץ: ‎-p wa‎ היא כתיבה (w) ושינוי תכונות (a), ו־‎-k‎ נותנת מפתח שיהיה קל לחפש. ‎auditctl -l‎ מציגה את הכללים שפעילים עכשיו.', 'auditd records kernel events to /var/log/audit/audit.log: who opened, changed or ran a file. This is the accounting part: knowing later what happened. auditctl -w /etc/passwd -p wa -k passwd_watch watches the file: -p wa is write (w) and attribute change (a), and -k gives a key that is easy to search for. auditctl -l shows the rules active right now.') },
      { type: 'output', prompt: T('על שרת Ubuntu אמיתי הוסיפו כלל עם ‎auditctl -w /etc/passwd -p wa -k passwd_watch‎, ואז הריצו ‎auditctl -l‎. מה הודפס?', 'On a real Ubuntu server a rule was added with auditctl -w /etc/passwd -p wa -k passwd_watch, then auditctl -l ran. What was printed?'), rec: 'p14-auditctl', wrongText: ['No rules', '-w /etc/passwd -p rwxa -k passwd_watch'] },
      { type: 'output', prompt: T('אחר כך הריצו ‎chmod 644 /etc/passwd‎, וחיפשו עם ‎ausearch -k passwd_watch --format text‎ (השעה הוחלפה בתבנית). מה הודפסה השורה האחרונה?', 'Next chmod 644 /etc/passwd ran, and ausearch -k passwd_watch --format text searched for it (the time replaced by a placeholder). What was the last line?'), rec: 'p14-audit-text', wrongText: ['At <time> root, acting as root, successfully opened-file /etc/passwd using /usr/bin/cat', '<no matches>'] },
      { type: 'teach', cmd: 'audit.rules', name: 'rules that survive a reboot', text: T('כלל של auditctl נעלם באתחול. כללים קבועים כותבים בקבצים ב־‎/etc/audit/rules.d/‎, ו־augenrules מחברת אותם לקובץ ‎/etc/audit/audit.rules‎ שנטען בהפעלה. ‎-D‎ מוחקת כללים ישנים, ‎-b‎ קובעת את גודל התור, ו־‎-e 2‎ בסוף נועלת את הכללים עד האתחול הבא, כדי שתוקף לא יכבה אותם. ‏aureport מסכמת את הלוג, למשל ‎aureport -k --summary‎ לפי מפתח.', 'An auditctl rule is gone after a reboot. Permanent rules go in files in /etc/audit/rules.d/, and augenrules joins them into /etc/audit/audit.rules, which is loaded at start. -D deletes old rules, -b sets the queue size, and -e 2 at the end locks the rules until the next boot, so an attacker cannot turn them off. aureport sums up the log, for example aureport -k --summary by key.') },
      { type: 'output', prompt: T('על אותו שרת הריצו ‎aureport -k --summary -i‎. מה הודפס?', 'On the same server aureport -k --summary -i ran. What was printed?'), rec: 'p14-aureport', wrongText: ['\nKey Summary Report\n===========================\ntotal key\n===========================\n0 passwd_watch', 'aureport: no audit log found'] },
      { type: 'terminal', prompt: T('הקובץ sec/audit.rules הוא קובץ כללים של auditd. כמה קבצים הוא שומר עליהם? ספרו את השורות שמתחילות ב־‎-w‎', 'The file sec/audit.rules is an auditd rules file. How many files does it watch? Count the lines that start with -w'), hint: T("grep -c '^-w' sec/audit.rules", "grep -c '^-w' sec/audit.rules"), ask: T('כמה קבצים?', 'How many files?'), goal: (sh, log) => p14Shown(log, "grep -c '^-w' sec/audit.rules"), solve: ["grep -c '^-w' sec/audit.rules"] },
      { type: 'teach', known: true, cmd: 'audit2allow', name: 'when SELinux says no', text: T('כש־SELinux חוסמת משהו, היא כותבת שורת AVC ל־audit.log. ‏‎ausearch -m AVC -ts recent‎ מוצאת אותן. ‏sealert (מהחבילה setroubleshoot) קוראת את הלוג ומסבירה בשפה פשוטה מה קרה ואיך לתקן. audit2why מסבירה למה, ו־audit2allow כותבת כלל שמתיר את מה שנחסם: ‎audit2allow -M myfix‎ יוצרת מודול שמתקינים עם ‎semodule -i myfix.pp‎. סדר נכון: קודם תווית (restorecon) או boolean ‏(‎setsebool -P‎), ורק בסוף מודול משלכם.', 'When SELinux blocks something, it writes an AVC line to audit.log. ausearch -m AVC -ts recent finds them. sealert (from the setroubleshoot package) reads the log and explains in plain words what happened and how to fix it. audit2why explains why, and audit2allow writes a rule that allows what was blocked: audit2allow -M myfix creates a module you install with semodule -i myfix.pp. The right order: first a label (restorecon) or a boolean (setsebool -P), and only last a module of your own.') },
      { type: 'output', prompt: T('הקובץ avc.log מכיל שורת AVC אחת: התהליך httpd (בהקשר httpd_t) נחסם בקריאת קובץ עם התווית user_home_t. על שרת Ubuntu אמיתי הריצו עליו audit2allow. מה הודפס?', 'The file avc.log holds one AVC line: the process httpd (in the context httpd_t) was denied reading a file labeled user_home_t. On a real Ubuntu server audit2allow ran on it. What was printed?'), rec: 'p14-audit2allow', wrongText: ['\n\n#============= user_home_t ==============\nallow user_home_t httpd_t:file read;\n', 'audit2allow: no denials found'] },
      { type: 'choice', prompt: T('nginx לא מצליח לקרוא קבצים שהעתקתם מתיקיית הבית ל־‎/var/www‎, ו־ls -Z מראה user_home_t. מה התיקון הנכון?', 'nginx cannot read files you copied from a home folder to /var/www, and ls -Z shows user_home_t. What is the right fix?'), options: ['restorecon -Rv /var/www', 'audit2allow -M webfix', 'setenforce 0', 'chmod 777 /var/www'], answer: 'restorecon -Rv /var/www',
        why: { 'audit2allow -M webfix': T('מודול יתיר לשרת לקרוא כל קובץ בית. הבעיה היא תווית שגויה.', 'A module would let the server read every home file. The problem is a wrong label.'), 'setenforce 0': T('זה מכבה את ההגנה בשביל כל השרת.', 'That turns protection off for the whole server.'), 'chmod 777 /var/www': T('ההרשאות לא הבעיה, ו־777 פותחת את הקבצים לכולם.', 'Permissions are not the problem, and 777 opens the files to everyone.') } },
    ] },
    { title: T('fail2ban ותכונות קבצים', 'fail2ban and file attributes'), exercises: [
      { type: 'teach', cmd: 'fail2ban', name: 'ban repeated failures', text: T('fail2ban קוראת לוגים, ואם כתובת IP נכשלת שוב ושוב (למשל בסיסמת SSH), היא חוסמת אותה בחומת האש לזמן מה. כל שירות מוגדר ב"כלא" (jail). ‏maxretry הוא מספר הכישלונות, ‏findtime חלון הזמן שבו סופרים, ו־bantime כמה זמן החסימה. את ‎/etc/fail2ban/jail.conf‎ לא עורכים, כי עדכון ידרוס אותו. כותבים את השינויים ב־‎/etc/fail2ban/jail.local‎.', 'fail2ban reads logs, and if an IP address fails again and again (for example an SSH password), it blocks it in the firewall for a while. Each service is set up in a "jail". maxretry is the number of failures, findtime the window in which they are counted, and bantime how long the ban lasts. You do not edit /etc/fail2ban/jail.conf, because an update overwrites it. You write your changes in /etc/fail2ban/jail.local.') },
      { type: 'output', prompt: T('על שרת Ubuntu אמיתי הפעילו את הכלא sshd ב־jail.local. חסמו ביד את 203.0.113.7 עם ‎fail2ban-client set sshd banip‎, והציגו את מצב הכלא (סימני העץ הוסרו). מה הודפס?', 'On a real Ubuntu server the sshd jail was turned on in jail.local. 203.0.113.7 was banned by hand with fail2ban-client set sshd banip, then the sshd jail status was shown (tree marks removed). What was printed?'), rec: 'p14-f2b-ban', wrongText: ['1\nStatus for the jail: sshd\n- Filter\n - Currently failed:\t0\n - Total failed:\t0\n - Journal matches:\t_SYSTEMD_UNIT=sshd.service + _COMM=sshd\n- Actions\n - Currently banned:\t0\n - Total banned:\t0\n - Banned IP list:\t', '0\nERROR NOK: (\'sshd\',)'] },
      { type: 'terminal', prompt: T('הקובץ sec/jail.local הוא ההגדרות של fail2ban בשרת. אחרי כמה כישלונות נחסם מי שמתחבר ל־sshd? הציגו את הקובץ. שימו לב: הגדרה בתוך ‎[sshd]‎ גוברת על ‎[DEFAULT]‎', 'The file sec/jail.local holds the fail2ban settings on a server. After how many failures is someone connecting to sshd banned? Show the file. Note: a setting inside [sshd] beats [DEFAULT]'), hint: T('cat sec/jail.local', 'cat sec/jail.local'), ask: T('אחרי כמה כישלונות?', 'After how many failures?'), goal: (sh, log) => p14Shown(log, 'cat sec/jail.local') || p14Shown(log, 'tail -3 sec/jail.local') || p14Shown(log, 'tail -1 sec/jail.local'), solve: ['tail -1 sec/jail.local'] },
      { type: 'teach', cmd: 'chattr +i', name: 'a file even root cannot change', text: T('לקבצים ב־ext4 וב־XFS יש תכונות מעבר להרשאות. ‎chattr +i‎ הופכת קובץ לבלתי ניתן לשינוי (immutable): אי אפשר לכתוב, למחוק או לשנות שם, גם לא root, עד ‎chattr -i‎. ‎chattr +a‎ מתירה רק הוספה לסוף, טוב ללוגים. ‏lsattr מציגה את התכונות: i או a בשורה. כך שומרים על קובץ כמו ‎/etc/resolv.conf‎ מפני תוכנה שדורסת אותו.', 'Files on ext4 and XFS have attributes beyond permissions. chattr +i makes a file immutable: nobody can write, delete or rename it, not even root, until chattr -i. chattr +a allows only adding to the end, good for logs. lsattr shows the attributes: an i or an a in the line. This way you protect a file like /etc/resolv.conf from a program that overwrites it.') },
      { type: 'output', prompt: T('על שרת Ubuntu אמיתי, בתור root, יצרו את keep.txt והריצו עליו ‎chattr +i‎. אחר כך הריצו lsattr, ‏‎rm -f keep.txt‎ וקוד היציאה. מה הודפס?', 'On a real Ubuntu server, as root, keep.txt was created and chattr +i ran on it. Then lsattr, rm -f keep.txt and the exit code ran. What was printed?'), rec: 'p14-lsattr', wrongText: ['----i---------e------- keep.txt\nexit: 0', '--------------e------- keep.txt\nexit: 0'] },
      { type: 'output', prompt: T('app.log מכיל את השורה one, ועליו ‎chattr +a‎. על שרת Ubuntu אמיתי, בתור root, הוסיפו את two עם ‎>>‎, ניסו לדרוס עם ‎echo three >‎, והציגו את הקובץ. מה הודפס?', 'app.log holds the line one, with chattr +a on it. On a real Ubuntu server, as root, two was added with >>, then echo three > tried to overwrite it, and the file was shown. What was printed?'), rec: 'p14-chattr-a', wrongText: ['three', 'bash: line 1: app.log: Operation not permitted\none'] },
      { type: 'teach', cmd: '/etc/issue', name: 'login banners', text: T('תקנים של אבטחה דורשים אזהרה לפני כניסה, למשל "Authorized users only", ושהיא לא תחשוף את גרסת המערכת. ‏‎/etc/issue‎ מוצג לפני כניסה במסוף המקומי (‎\\n‎ שם המחשב, ‎\\l‎ המסוף). ‏‎/etc/issue.net‎ לפני כניסה מרחוק: ב־SSH רק אם sshd_config מכיל ‎Banner /etc/issue.net‎. ‏‎/etc/motd‎ מוצג אחרי הכניסה. גם לבחור שירותים זה הקשחה: Telnet ו־FTP שולחים סיסמאות בטקסט גלוי, ו־TFTP בלי שום סיסמה. במקומם SSH ו־SFTP.', 'Security standards require a warning before login, for example "Authorized users only", that does not reveal the system version. /etc/issue is shown before a login on the local console (\\n the host name, \\l the terminal). /etc/issue.net before a remote login: with SSH only if sshd_config holds Banner /etc/issue.net. /etc/motd is shown after login. Choosing services is hardening too: Telnet and FTP send passwords in plain text, and TFTP has no password at all. Use SSH and SFTP instead.') },
      { type: 'output', prompt: T('על שרת Ubuntu אמיתי הריצו ‎cat /etc/issue‎, ‏‎cat /etc/issue.net‎ ו־‎ls /etc/motd‎. מה הודפס?', 'On a real Ubuntu server cat /etc/issue, cat /etc/issue.net and ls /etc/motd ran. What was printed?'), rec: 'p14-issue', wrongText: ['Authorized users only\n\nAuthorized users only\n/etc/motd', 'Ubuntu 24.04.5 LTS server tty1\n\nUbuntu 24.04.5 LTS\n/etc/motd'] },
      { type: 'match', prompt: T('התאימו כל שירות ישן לתחליף הבטוח שלו', 'Match each old service to its safe replacement'), pairs: [['Telnet', 'SSH'], ['FTP', 'SFTP'], ['TFTP', T('רק ברשת סגורה, ל־PXE', 'only on a closed network, for PXE')], ['/etc/issue.net', T('אזהרה בלי גרסה', 'a warning with no version')]] },
    ] },
  ],
  boss: { title: CHALLENGE, text: T('מקשיחים שרת חדש לפני שהוא עולה לאוויר.', 'Hardening a new server before it goes live.'), exercises: [
    { type: 'scenario', prompt: T('dana ננעלה אחרי שלוש סיסמאות שגויות. שחררו אותה עם faillock', 'dana was locked after three wrong passwords. Unlock her with faillock'), hint: T('faillock --user … --reset', 'faillock --user … --reset'), accept: p14Sudo('faillock --user dana --reset', 'faillock --reset --user dana') },
    { type: 'scenario', prompt: T('צרפו את השרת לדומיין ad.example.com עם realm', 'Join the server to the domain ad.example.com with realm'), hint: T('realm join', 'realm join'), accept: p14Sudo('realm join ad.example.com', 'realm join -v ad.example.com', 'realm join --verbose ad.example.com') },
    { type: 'scenario', prompt: T('הגנו על ‎/etc/resolv.conf‎ כך שאף תוכנה, גם לא root, לא תוכל לשנות אותו', 'Protect /etc/resolv.conf so no program, not even root, can change it'), hint: T('chattr +i', 'chattr +i'), accept: p14Sudo('chattr +i /etc/resolv.conf') },
    { type: 'scenario', prompt: T('ב־auditd, הוסיפו כלל ששומר על ‎/etc/shadow‎ מפני כתיבה ושינוי תכונות, עם המפתח shadow_watch', 'In auditd, add a rule that watches /etc/shadow for writes and attribute changes, with the key shadow_watch'), hint: T('auditctl -w … -p wa -k …', 'auditctl -w … -p wa -k …'), accept: p14Sudo('auditctl -w /etc/shadow -p wa -k shadow_watch', 'auditctl -w /etc/shadow -k shadow_watch -p wa', 'auditctl -p wa -w /etc/shadow -k shadow_watch') },
    { type: 'scenario', prompt: T('שחררו את 203.0.113.7 מהכלא sshd של fail2ban', 'Unban 203.0.113.7 from the fail2ban sshd jail'), hint: T('fail2ban-client set sshd …', 'fail2ban-client set sshd …'), accept: p14Sudo('fail2ban-client set sshd unbanip 203.0.113.7', 'fail2ban-client unban 203.0.113.7') },
  ] },
};

COURSE.push(UNIT_92);
